55: function makePlatformDetail(p) {
56:   const rng = mulberry32((p.x * 17 + p.y * 31 + p.w * 7) | 0);
57:   const bolts = [];
58:   for (let i = 6; i < p.w - 6; i += 18) {
59:     bolts.push({ x: p.x + i, y: p.y + 8 + (i % 3 === 0 ? 0 : 4) });
60:   }
61:   const cracks = [];
62:   for (let i = 0; i < 4; i++) {
63:     cracks.push({
64:       x: 12 + rng() * Math.max(1, p.w - 24),
65:       y: 8 + rng() * Math.max(1, Math.min(38, p.h - 8)),
66:       dx: rand(5, 17), dy: rand(6, 20)
67:     });
68:   }
69:   const stains = [];
70:   for (let i = 0; i < 3; i++) {
71:     stains.push({
72:       x: 10 + rng() * Math.max(1, p.w - 20),
73:       y: 22 + rng() * Math.min(45, Math.max(1, p.h - 22)),
74:       w: 5 + rng() * 16, h: 2 + rng() * 5, a: 0.06 + rng() * 0.09
75:     });
76:   }
77:   return { bolts, cracks, stains, rebar: p.kind === 'ground' && (p.x === 0 || true) };
78: }
