269:   onKeyDown(e) {
270:     const code = e.code;
271:     const handled = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space', 'KeyA', 'KeyD', 'KeyW', 'KeyS', 'ShiftLeft', 'ShiftRight', 'KeyF', 'KeyV', 'KeyG', 'KeyR', 'KeyQ', 'KeyE', 'KeyM', 'Escape', 'KeyP', 'Digit1', 'Digit2', 'Digit3', 'Digit4', 'Digit5'];
272:     if (this.state === 'menu' && (code === 'Enter' || code === 'Space')) {
273:       e.preventDefault();
274:       this.startCampaign();
275:       return;
276:     }
277:     if (this.state !== 'playing') {
278:       if (code === 'Escape' && this.state === 'paused') { e.preventDefault(); this.resume(); return; }
279:       return;
280:     }
281:     if (handled.includes(code)) e.preventDefault();
282:     if (code === 'ArrowLeft' || code === 'KeyA') this.input.left = true;
283:     else if (code === 'ArrowRight' || code === 'KeyD') this.input.right = true;
284:     else if (code === 'Space' || code === 'KeyW' || code === 'ArrowUp') {
285:       if (!e.repeat) this.player.jumpBuffer = JUMP_BUFFER;
286:       this.input.jumpHeld = true;
287:     } else if (code === 'ShiftLeft' || code === 'ShiftRight') {
288:       if (!e.repeat) this.roll();
289:     } else if (code === 'KeyF' || code === 'KeyV') {
290:       if (!e.repeat) this.knife();
291:     } else if (code === 'KeyG') {
292:       if (!e.repeat) this.throwGrenade();
293:     } else if (code === 'KeyR') {
294:       if (!e.repeat) this.startReload();
295:     } else if (code === 'KeyQ') {
296:       if (!e.repeat) this.cycleWeapon(-1);
297:     } else if (code === 'KeyE') {
298:       if (!e.repeat) this.cycleWeapon(1);
299:     } else if (code === 'KeyM') {
300:       this.toggleMute();
301:     } else if (code === 'Escape' || code === 'KeyP') {
302:       if (!e.repeat) this.pause();
303:     } else if (/^Digit[1-5]$/.test(code)) {
304:       const idx = Number(code.slice(-1)) - 1;
305:       this.selectWeapon(WEAPON_ORDER[idx]);
306:     }
307:   }
