615:   /* ============================================================
616:      Main loop
617:      ============================================================ */
618:   loop(timestamp) {
619:     if (!this.lastFrame) this.lastFrame = timestamp;
620:     const frame = Math.min(0.05, (timestamp - this.lastFrame) / 1000);
621:     this.lastFrame = timestamp;
622:     this.acc += frame;
623:     let steps = 0;
624:     while (this.acc >= FIXED && steps < 5) {
625:       this.tick(FIXED);
626:       this.acc -= FIXED;
627:       steps++;
628:     }
629:     if (steps === 5) this.acc = 0;
630:     this.renderer.render();
631:     requestAnimationFrame(this._loop);
632:   }
633: 
634:   tick(dt) {
635:     if (this.state !== 'paused' && this.state !== 'gameover') {
636:       this.animTime += dt;
637:       this.flash = Math.max(0, this.flash - dt * 2.6);
638:       this.hitMarker = Math.max(0, this.hitMarker - dt);
639:       this.crosshairSpread = approach(this.crosshairSpread, 0, dt * 24);
640:       this.lightning = Math.max(0, this.lightning - dt * 4.2);
641:       this.lightningTimer -= dt;
642:       if (this.lightningTimer <= 0) {
643:         this.lightningTimer = rand(4.5, 10);
644:         this.lightning = rand(0.6, 1);
645:       }
646:       this.updateTimers(dt);
647:     }
648:     if (this.state === 'menu') {
649:       this.camera.x = 420 + Math.sin(this.animTime * 0.09) * 24;
650:       this.updateMouseWorld();
651:       this.player.aimAngle = -0.03 + Math.sin(this.animTime * 0.5) * 0.02;
652:       this.player.muzzleTimer = 0;
653:     } else if (this.state === 'playing') {
654:       this.updatePlaying(dt);
655:     } else if (this.state === 'dying') {
656:       this.updateDying(dt);
657:     } else if (this.state === 'paused') {
658:       this.updateCamera(dt * 0.2);
659:     }
660:   }
661: 
662:   updateTimers(dt) {
663:     for (let i = this.timers.length - 1; i >= 0; i--) {
664:       const t = this.timers[i];
665:       t.time -= dt;
666:       if (t.time <= 0) {
667:         this.timers.splice(i, 1);
668:         try { t.fn(); } catch (err) { console.error(err); }
669:       }
670:     }
671:   }
672: 
673:   addTimer(delay, fn) {
674:     this.timers.push({ time: delay, fn });
675:   }
676: 
677:   updatePlaying(dt) {
678:     this.levelTime += dt;
679:     this.campaignTime += dt;
680:     this.updatePlayer(dt);
681:     this.updateBullets(dt);
682:     this.updateGrenades(dt);
683:     this.updateEnemies(dt);
684:     this.updateBoss(dt);
685:     this.updatePickups(dt);
686:     this.updateDestructibles(dt);
687:     this.updateHazards(dt);
688:     this.updateParticles(dt);
689:     this.updateEffects(dt);
690:     this.updateDecals(dt);
691:     this.updateTexts(dt);
692:     this.updateCamera(dt);
693:     this.updateMouseWorld();
694:     this.updateCombo(dt);
695:     this.updateFieldTips(dt);
696:     this.checkCheckpoints();
697:     this.checkExit();
698:     this.updateHUD();
699:     this.audio.update(dt, this.combatIntensity());
700:     if (this.player.health <= 0 && this.state === 'playing') this.beginDeath();
701:   }
702: 
703:   updateDying(dt) {
704:     this.deathTimer -= dt;
705:     this.updateParticles(dt * 0.45);
706:     this.updateEffects(dt * 0.45);
707:     this.updateTexts(dt * 0.45);
708:     this.updateCamera(dt * 0.3);
709:     this.flash = Math.max(0, this.flash - dt * 1.2);
710:     if (this.deathTimer <= 0) this.showGameOver();
711:   }
