718:   beginDeath() {
719:     if (this.state !== 'playing') return;
720:     this.player.dead = true;
721:     this.state = 'dying';
722:     this.deathTimer = 1.35;
723:     this.input.firing = false;
724:     this.touch.fire = false;
725:     this.audio.hurt();
726:     this.audio.stopMusic();
727:     this.camera.shake = 13;
728:     this.spawnBlood(this.player.x + this.player.w / 2, this.player.y + 26, 26);
729:     this.flash = 0.8;
730:     document.body.classList.remove('is-playing');
731:   }
732: 
733:   combatIntensity() {
734:     if (!this.player || !this.runtime) return 0;
735:     let near = 0;
736:     const cx = this.player.x;
737:     for (const e of this.runtime.enemies) {
738:       if (!e.dead && Math.abs(e.x - cx) < 900) near++;
739:     }
740:     if (this.boss && this.boss.active && !this.boss.dead) near += 4;
741:     return clamp(near / 7, 0, 1);
742:   }
743: 
744:   /* ============================================================
745:      Player movement and combat
746:      ============================================================ */
747:   updatePlayer(dt) {
748:     const p = this.player;
749:     if (!p || p.dead) return;
750:     p.invuln = Math.max(0, p.invuln - dt);
751:     p.rollCd = Math.max(0, p.rollCd - dt);
752:     p.knifeCd = Math.max(0, p.knifeCd - dt);
753:     p.knifeTimer = Math.max(0, p.knifeTimer - dt);
754:     p.fireCd = Math.max(0, p.fireCd - dt);
755:     p.muzzleTimer = Math.max(0, p.muzzleTimer - dt);
756:     p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
757:     p.landTimer = Math.max(0, p.landTimer - dt);
758: 
759:     this.updateMouseWorld();
760:     let aiming = false;
761:     if (this.touchMode && (this.touch.fire || this.input.firing)) {
762:       const target = this.findAimTarget();
763:       if (target) {
764:         const sx = p.x + p.w / 2;
765:         const sy = p.y + 22;
766:         p.aimAngle = Math.atan2(target.y - sy, target.x - sx);
767:         aiming = true;
768:       }
769:     }
770:     if (!aiming) {
771:       const sx = p.x + p.w / 2;
772:       const sy = p.y + 22;
773:       p.aimAngle = Math.atan2(this.mouse.y - sy, this.mouse.x - sx);
774:     }
775:     p.facing = Math.cos(p.aimAngle) >= 0 ? 1 : -1;
776: 
777:     const left = this.input.left || this.touch.left;
778:     const right = this.input.right || this.touch.right;
779:     const moveDir = (right ? 1 : 0) - (left ? 1 : 0);
780: 
781:     if (p.rollTimer > 0) {
782:       p.rollTimer -= dt;
783:       p.vx = p.rollDir * 690;
784:       p.vy = Math.min(p.vy + GRAVITY * 0.72 * dt, MAX_FALL);
785:       if (p.rollTimer <= 0) p.vx *= 0.35;
786:     } else {
787:       const targetSpeed = moveDir * PLAYER_SPEED;
788:       const accel = p.grounded ? PLAYER_ACCEL : PLAYER_ACCEL * 0.58;
789:       if (moveDir !== 0) {
790:         p.vx = approach(p.vx, targetSpeed, accel * dt);
791:       } else {
792:         p.vx = approach(p.vx, 0, (p.grounded ? 2500 : 520) * dt);
793:       }
794:       p.vy = Math.min(p.vy + GRAVITY * dt, MAX_FALL);
795:       if (!this.input.jumpHeld && p.vy < -180) {
796:         p.vy += GRAVITY * 1.45 * dt;
797:       }
798:     }
799: 
800:     // Jump with coyote time + input buffer.
801:     if (p.coyote > 0) p.coyote -= dt;
802:     if (p.jumpBuffer > 0 && p.coyote > 0 && p.rollTimer <= 0) {
803:       p.vy = -PLAYER_JUMP;
804:       p.grounded = false;
805:       p.coyote = 0;
806:       p.jumpBuffer = 0;
807:       this.audio.jump();
808:       this.addDust(p.x + p.w / 2, p.y + p.h, 4, '#b6a07c');
809:     }
810: 
811:     const wasGrounded = p.grounded;
812:     const fallSpeed = p.vy;
813:     this.moveActor(p, dt);
814:     if (!wasGrounded && p.grounded && fallSpeed > 360) {
815:       this.audio.land(clamp(fallSpeed / 800, 0.4, 1.3));
816:       this.addDust(p.x + p.w / 2, p.y + p.h, 7, '#b8a37f');
817:       this.camera.shake = Math.max(this.camera.shake, clamp(fallSpeed / 260, 1, 4));
818:     }
819: 
820:     if (p.grounded) {
821:       p.coyote = COYOTE_TIME;
822:     }
823: 
824:     // Run animation + footfall dust.
825:     p.runPhase += Math.abs(p.vx) * dt * 0.075;
826:     if (p.grounded && Math.abs(p.vx) > 90) {
827:       p.stepTimer -= dt;
828:       if (p.stepTimer <= 0) {
829:         p.stepTimer = 0.19;
830:         this.addDust(p.x + p.w / 2 - p.facing * 9, p.y + p.h, 2, 'rgba(196,178,146,.5)');
831:         if (p.grounded && Math.random() < 0.25) this.audio.land(0.25);
832:       }
833:     } else {
834:       p.stepTimer = 0;
835:     }
836: 
837:     // Weapon reload.
838:     if (p.reloading) {
839:       p.reloadTimer -= dt;
840:       p.reloadProgress = 1 - clamp(p.reloadTimer / p.reloadDuration, 0, 1);
841:       if (p.reloadTimer <= 0) this.finishReload();
842:     }
843: 
844:     // Fire control. Auto weapons fire while held, semi-auto on a fresh trigger.
845:     const cfg = WEAPONS[p.weaponId];
846:     if (cfg && !p.reloading && p.fireCd <= 0) {
847:       const wantFire = cfg.auto ? (this.input.firing || this.touch.fire) : (this.input.firePressed || this.touch.fire);
848:       if (wantFire) this.fireWeapon();
849:     }
850:     this.input.firePressed = false;
851: 
852:     // World bounds and pits.
853:     p.x = clamp(p.x, 8, this.level.width - p.w - 8);
854:     if (p.y > 880) this.fallRespawn();
855:   }
856: 
857:   moveActor(a, dt) {
858:     const platforms = this.runtime.platforms;
859:     a.x += a.vx * dt;
860:     for (const plat of platforms) {
861:       if (!rectsOverlap(a, plat)) continue;
862:       if (a.vx > 0) a.x = plat.x - a.w - 0.01;
863:       else if (a.vx < 0) a.x = plat.x + plat.w + 0.01;
864:       a.vx = 0;
865:     }
866:     a.grounded = false;
867:     a.y += a.vy * dt;
868:     for (const plat of platforms) {
869:       if (!rectsOverlap(a, plat)) continue;
870:       if (a.vy > 0) {
871:         a.y = plat.y - a.h - 0.01;
872:         a.vy = 0;
873:         a.grounded = true;
874:       } else if (a.vy < 0) {
875:         a.y = plat.y + plat.h + 0.01;
876:         a.vy = 0;
877:       }
878:     }
879:   }
880: 
881:   pointSolid(x, y) {
882:     for (const p of this.runtime.platforms) {
883:       if (x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h) return true;
884:     }
885:     return false;
886:   }
887: 
888:   hasSupport(x, y) {
889:     return this.pointSolid(x, y);
890:   }
891: 
892:   fireWeapon() {
893:     const p = this.player;
894:     if (!p || p.dead || p.reloading || p.fireCd > 0) return;
895:     const id = p.weaponId;
896:     const cfg = WEAPONS[id];
897:     if (!cfg) return;
898:     const ammo = p.ammo[id];
899:     if (!ammo) return;
900:     if (ammo.mag <= 0) {
901:       if (ammo.reserve > 0) {
902:         this.startReload();
903:       } else {
904:         this.audio.empty();
905:         p.fireCd = 0.22;
906:         this.showToast('WEAPON EMPTY', `${cfg.name} — NO AMMUNITION`, 1500);
907:       }
908:       this.input.firePressed = false;
909:       return;
910:     }
911: 
912:     ammo.mag--;
913:     p.fireCd = cfg.fireDelay;
914:     p.muzzleTimer = 0.058;
915:     p.muzzleSeed = rand(0, TAU);
916:     p.reloading = false;
917:     p.reloadProgress = 0;
918:     const sx = p.x + p.w / 2;
919:     const sy = p.y + 22;
920:     const baseAngle = p.aimAngle;
921:     const muzzleDist = id === 'rocket' ? 28 : 26;
922:     const spread = cfg.spread;
923:     const pelletCount = cfg.pellets || 1;
924:     for (let i = 0; i < pelletCount; i++) {
925:       const angle = baseAngle + rand(-spread, spread) + (pelletCount > 1 ? rand(-0.025, 0.025) : 0);
926:       const speed = cfg.bulletSpeed * rand(0.96, 1.04);
927:       this.runtime.bullets.push({
928:         owner: 'player',
929:         x: sx + Math.cos(angle) * muzzleDist,
930:         y: sy + Math.sin(angle) * muzzleDist,
931:         px: sx + Math.cos(angle) * muzzleDist,
932:         py: sy + Math.sin(angle) * muzzleDist,
933:         vx: Math.cos(angle) * speed,
934:         vy: Math.sin(angle) * speed,
935:         life: cfg.id === 'rifle' ? 1.35 : 1.05,
936:         damage: cfg.damage,
937:         color: cfg.tracer,
938:         rocket: id === 'rocket',
939:         explosive: cfg.explosive || null,
940:         angle
941:       });
942:     }
943: 
944:     // Physical feedback.
945:     const recoil = cfg.recoil || 2;
946:     p.vx -= Math.cos(baseAngle) * recoil * 5;
947:     this.camera.shake = Math.max(this.camera.shake, cfg.shake || 2);
948:     this.crosshairSpread = Math.min(15, this.crosshairSpread + recoil * 0.9);
949:     this.flash = Math.max(this.flash, id === 'rocket' ? 0.42 : 0.1);
950:     const pan = clamp((p.x - (this.camera.x + this.view.w / 2)) / (this.view.w / 2), -0.8, 0.8);
951:     this.audio.shot(cfg.sound, pan);
952:     if (id !== 'rocket') {
953:       const perp = baseAngle + Math.PI / 2;
954:       this.addParticle({
955:         type: 'casing', x: sx + Math.cos(baseAngle) * 20, y: sy + Math.sin(baseAngle) * 20,
956:         vx: Math.cos(perp) * rand(70, 140) + rand(-20, 20),
957:         vy: -rand(100, 210), life: 0.9, size: 2.2, color: '#d6ad68',
958:         gravity: 900, angle: rand(0, TAU), spin: rand(-12, 12)
959:       });
960:       for (let i = 0; i < 2; i++) {
961:         this.addParticle({
962:           type: 'smoke', x: sx + Math.cos(baseAngle) * (20 + i * 8), y: sy + Math.sin(baseAngle) * (20 + i * 8),
963:           vx: Math.cos(baseAngle) * rand(20, 60) + rand(-20, 20),
964:           vy: Math.sin(baseAngle) * rand(20, 60) - rand(10, 30),
965:           life: rand(0.22, 0.4), size: rand(3, 6), color: 'rgba(170,155,130,.16)', gravity: -20
966:         });
967:       }
968:     }
969:     if (ammo.mag === 0 && ammo.reserve > 0) {
970:       this.addTimer(0.22, () => {
971:         if (this.player && this.player.weaponId === id) this.startReload();
972:       });
973:     }
974:     this.weaponDirty = true;
975:   }
976: 
977:   startReload() {
978:     const p = this.player;
979:     if (!p || p.dead || p.reloading) return;
980:     const cfg = WEAPONS[p.weaponId];
981:     const ammo = p.ammo[p.weaponId];
982:     if (!cfg || !ammo) return;
983:     if (ammo.mag >= cfg.magSize) return;
984:     if (ammo.reserve <= 0) {
985:       this.showToast('OUT OF AMMO', 'FIND AN AMMUNITION CACHE', 1500);
986:       this.audio.empty();
987:       return;
988:     }
989:     p.reloading = true;
990:     p.reloadTimer = cfg.reloadTime;
991:     p.reloadDuration = cfg.reloadTime;
992:     p.reloadProgress = 0;
993:     this.audio.reload();
994:   }
995: 
996:   finishReload() {
997:     const p = this.player;
998:     if (!p) return;
999:     const cfg = WEAPONS[p.weaponId];
1000:     const ammo = p.ammo[p.weaponId];
1001:     if (!cfg || !ammo) return;
1002:     const need = cfg.magSize - ammo.mag;
1003:     const take = Math.min(need, ammo.reserve);
1004:     ammo.mag += take;
1005:     ammo.reserve -= take;
1006:     p.reloading = false;
1007:     p.reloadTimer = 0;
1008:     p.reloadProgress = 0;
1009:     this.audio.reloadDone();
1010:     this.weaponDirty = true;
1011:   }
1012: 
1013:   selectWeapon(id) {
1014:     if (!id) return;
1015:     if (!this.unlocked.includes(id)) {
1016:       this.showToast('WEAPON LOCKED', `CLEAR SECTOR 0${Math.max(1, WEAPONS[id].slot - 1)} TO UNLOCK`, 1500);
1017:       return;
1018:     }
1019:     const p = this.player;
1020:     if (!p || p.dead || p.weaponId === id) return;
1021:     p.weaponId = id;
1022:     p.reloading = false;
