37:     this.cssW = 1280;
38:     this.cssH = 720;
39:     this.backdrop = null;
40:     this.backdropId = -1;
41:     this.rainSeeds = Array.from({ length: 150 }, () => ({
42:       x: Math.random(), y: Math.random(), s: rand(0.7, 1.3), a: rand(0.16, 0.5)
43:     }));
44:     this.ashSeeds = Array.from({ length: 70 }, () => ({
45:       x: Math.random(), y: Math.random(), s: rand(0.4, 1.4), a: rand(0.08, 0.32), p: rand(0.4, 1.8)
46:     }));
47:     this.emberSeeds = Array.from({ length: 65 }, () => ({
48:       x: Math.random(), y: Math.random(), s: rand(0.7, 2.1), a: rand(0.2, 0.7), p: rand(0.6, 2)
49:     }));
50:     this.moteSeeds = Array.from({ length: 50 }, () => ({
51:       x: Math.random(), y: Math.random(), s: rand(0.6, 2.2), a: rand(0.07, 0.25), p: rand(0.3, 1.3)
52:     }));
53:   }
