55:   resize() {
56:     const cssW = Math.max(320, window.innerWidth);
57:     const cssH = Math.max(320, window.innerHeight);
58:     const dpr = Math.min(window.devicePixelRatio || 1, 2);
59:     this.cssW = cssW;
60:     this.cssH = cssH;
61:     this.dpr = dpr;
62:     this.canvas.width = Math.round(cssW * dpr);
63:     this.canvas.height = Math.round(cssH * dpr);
64:     this.canvas.style.width = `${cssW}px`;
65:     this.canvas.style.height = `${cssH}px`;
66:     if (cssW >= cssH) {
67:       this.viewH = 720;
68:       this.scale = Math.min(cssH / 720, cssW / 1000);
69:       this.viewW = cssW / this.scale;
70:       this.offsetX = 0;
71:       this.offsetY = (cssH - this.viewH * this.scale) / 2;
72:     } else {
73:       this.viewW = 760;
74:       this.viewH = 720;
75:       this.scale = Math.min(cssW / 760, cssH / 720);
76:       this.offsetX = (cssW - this.viewW * this.scale) / 2;
77:       this.offsetY = (cssH - this.viewH * this.scale) / 2;
78:     }
79:     this.game.view = {
80:       w: this.viewW, h: this.viewH, scale: this.scale,
81:       offsetX: this.offsetX, offsetY: this.offsetY, cssW, cssH, dpr
82:     };
83:   }
84: 
85:   prepareLevel(level, force = false) {
86:     if (!force && this.backdropId === level.id && this.backdrop) return;
87:     this.backdropId = level.id;
88:     const rng = mulberry32(level.skylineSeed || 1);
89:     const theme = level.theme;
90:     const makeLayer = (count, minW, maxW, minH, maxH, gap, bottom, windows) => {
91:       const arr = [];
92:       let x = -300;
93:       for (let i = 0; i < count; i++) {
94:         const w = minW + rng() * (maxW - minW);
95:         const h = minH + rng() * (maxH - minH);
96:         const b = {
97:           x, w, h, bottom, damaged: rng() < 0.42,
98:           roof: rng(), antenna: rng() < 0.16,
99:           tone: rng(),
100:           windows: []
101:         };
102:         if (windows) {
103:           const cols = Math.max(1, Math.floor(w / 15));
104:           const rows = Math.max(1, Math.floor(h / 19));
105:           for (let cy = 0; cy < rows; cy++) {
106:             for (let cx = 0; cx < cols; cx++) {
107:               if (rng() < 0.23) {
108:                 b.windows.push({
109:                   x: 6 + cx * ((w - 12) / cols),
110:                   y: 12 + cy * ((h - 20) / rows),
111:                   w: Math.max(2.2, (w - 12) / cols * 0.34),
112:                   h: Math.max(2, (h - 20) / rows * 0.28),
113:                   warm: rng() < 0.72,
114:                   flick: rng()
115:                 });
116:               }
117:             }
118:           }
119:         }
120:         arr.push(b);
121:         x += w + gap * (0.4 + rng() * 1.1);
122:       }
123:       return arr;
124:     };
125:     const far = makeLayer(45, 38, 120, 65, 270, 15, HORIZON, false);
126:     const mid = makeLayer(38, 60, 180, 95, 360, 28, HORIZON + 5, true);
127:     const near = makeLayer(24, 90, 260, 50, 220, 60, HORIZON + 30, false);
128:     const smoke = [];
129:     for (let i = 0; i < 6; i++) {
130:       const b = mid[Math.floor(rng() * mid.length)] || mid[0];
131:       if (!b) break;
132:       smoke.push({
133:         x: b.x + b.w * (0.2 + rng() * 0.6), y: b.bottom - b.h - 8,
134:         s: 10 + rng() * 22, drift: rand(-12, 22), speed: rand(0.3, 0.8), phase: rng() * TAU
135:       });
136:     }
137:     const wires = [];
138:     for (let i = 0; i < 7; i++) {
139:       wires.push({
140:         x1: rng() * (level.width + 1200) - 200,
141:         x2: rng() * (level.width + 1200) - 200,
142:         y1: 180 + rng() * 210, y2: 180 + rng() * 210,
143:         sag: 30 + rng() * 75, alpha: 0.12 + rng() * 0.18
144:       });
145:     }
146:     const clouds = [];
147:     for (let i = 0; i < 11; i++) {
148:       clouds.push({
149:         x: rng() * 1.35 - 0.15, y: 0.04 + rng() * 0.38,
150:         w: 90 + rng() * 280, h: 12 + rng() * 30,
151:         a: 0.05 + rng() * 0.13, drift: rand(0.0008, 0.0035)
152:       });
153:     }
154:     const stars = [];
155:     if (theme.night) {
156:       for (let i = 0; i < 90; i++) {
157:         stars.push({ x: rng(), y: rng() * 0.5, s: rng() < 0.85 ? 1 : 1.8, p: rng() * TAU, a: 0.15 + rng() * 0.55 });
158:       }
159:     }
160:     const debris = [];
161:     for (let i = 0; i < 50; i++) {
162:       debris.push({
163:         x: rng() * (level.width + 1000) - 500,
164:         y: HORIZON + 10 + rng() * 80,
165:         s: 1 + rng() * 4, a: 0.08 + rng() * 0.22
166:       });
167:     }
168:     this.backdrop = { far, mid, near, smoke, wires, clouds, stars, debris };
169:   }
170: 
171:   render() {
172:     const g = this.game;
173:     const ctx = this.ctx;
174:     const d = this.dpr;
175:     ctx.setTransform(d, 0, 0, d, 0, 0);
176:     ctx.fillStyle = '#040708';
177:     ctx.fillRect(0, 0, this.cssW, this.cssH);
178:     ctx.save();
179:     ctx.translate(this.offsetX, this.offsetY);
180:     ctx.scale(this.scale, this.scale);
181:     ctx.beginPath();
182:     ctx.rect(0, 0, this.viewW, this.viewH);
183:     ctx.clip();
184: 
185:     this.drawSky();
186:     this.drawBackdrop();
187: 
188:     const shakeX = g.camera.shake > 0 ? rand(-1, 1) * g.camera.shake : 0;
189:     const shakeY = g.camera.shake > 0 ? rand(-1, 1) * g.camera.shake : 0;
190:     ctx.save();
191:     ctx.translate(-g.camera.x + shakeX, -g.camera.y + shakeY);
192: 
193:     this.drawDecorations();
194:     this.drawPlatforms();
195:     this.drawDecals();
196:     if (g.level.exit) this.drawExtraction(g.level.exit);
197:     this.drawCheckpoints();
198:     this.drawHazards();
199:     this.drawPickups();
200:     this.drawDestructibles();
201:     this.drawEnemies();
202:     if (g.player && g.state !== 'gameover' && g.state !== 'victory') this.drawPlayer(g.player);
203:     this.drawGate();
204:     this.drawBullets();
205:     this.drawGrenades();
206:     this.drawEffects();
207:     this.drawParticles();
208:     this.drawFloatingTexts();
209:     ctx.restore();
210: 
211:     this.drawObjectiveMarker();
212:     this.drawWeather();
213:     this.drawPostFx();
214:     if ((g.state === 'playing' || g.state === 'paused') && !g.touchMode) this.drawCrosshair();
215:     ctx.restore();
216:   }
