218:   /* ---------------------------------------------------------- */
219:   /* Sky and parallax                                            */
220:   /* ---------------------------------------------------------- */
221:   drawSky() {
222:     const ctx = this.ctx;
223:     const g = this.game;
224:     const t = g.level.theme;
225:     const w = this.viewW;
226:     const h = this.viewH;
227:     const cam = g.camera.x;
228:     const grad = ctx.createLinearGradient(0, 0, 0, h);
229:     grad.addColorStop(0, t.skyTop);
230:     grad.addColorStop(0.47, t.skyMid);
231:     grad.addColorStop(0.86, t.skyBottom);
232:     grad.addColorStop(1, t.skyBottom);
233:     ctx.fillStyle = grad;
234:     ctx.fillRect(0, 0, w, h);
235: 
236:     if (t.night) {
237:       for (const s of this.backdrop.stars) {
238:         const tw = 0.58 + Math.sin(g.animTime * 0.7 + s.p) * 0.42;
239:         ctx.globalAlpha = s.a * tw;
240:         ctx.fillStyle = '#cfdfe6';
241:         ctx.fillRect((s.x * w - cam * 0.003) % w, s.y * h, s.s, s.s);
242:       }
243:       ctx.globalAlpha = 1;
244:     }
245: 
246:     const sunX = w * t.sunX - cam * 0.012;
247:     const sunY = h * t.sunY;
248:     const sunR = t.night ? 34 : 48;
249:     const glow = ctx.createRadialGradient(sunX, sunY, 2, sunX, sunY, sunR * 4.8);
250:     glow.addColorStop(0, t.sun);
251:     glow.addColorStop(0.127, t.night ? 'rgba(188,216,228,.4)' : 'rgba(255,225,172,.74)');
252:     glow.addColorStop(0.36, t.night ? 'rgba(118,160,181,.13)' : 'rgba(233,151,81,.2)');
253:     glow.addColorStop(1, 'rgba(0,0,0,0)');
254:     ctx.fillStyle = glow;
255:     ctx.fillRect(sunX - sunR * 5, sunY - sunR * 5, sunR * 10, sunR * 10);
256:     ctx.fillStyle = t.sun;
257:     ctx.globalAlpha = t.night ? 0.66 : 0.93;
258:     ellipse(ctx, sunX, sunY, sunR, sunR);
259:     ctx.fill();
260:     ctx.globalAlpha = 1;
261:     if (t.night) {
262:       ctx.fillStyle = t.skyTop;
263:       ellipse(ctx, sunX + 12, sunY - 6, sunR * 0.92, sunR * 0.92);
264:       ctx.fill();
265:     }
266: 
267:     for (const c of this.backdrop.clouds) {
268:       const x = ((c.x + g.animTime * c.drift * 0.008) % 1.35) * w - 100;
269:       ctx.globalAlpha = c.a;
270:       const cg = ctx.createLinearGradient(x - c.w / 2, 0, x + c.w / 2, 0);
271:       cg.addColorStop(0, 'rgba(255,255,255,0)');
272:       cg.addColorStop(0.35, t.haze);
273:       cg.addColorStop(0.65, t.haze);
274:       cg.addColorStop(1, 'rgba(255,255,255,0)');
275:       ctx.fillStyle = cg;
276:       ellipse(ctx, x, c.y * h, c.w / 2, c.h, 0);
277:       ctx.fill();
278:     }
279:     ctx.globalAlpha = 1;
280: 
281:     if (!t.night) {
282:       ctx.save();
283:       ctx.globalCompositeOperation = 'screen';
284:       for (let i = 0; i < 5; i++) {
285:         const ang = -0.72 + i * 0.27;
286:         const x = sunX - Math.cos(ang) * 0 - cam * 0.01;
287:         ctx.globalAlpha = 0.028 + i * 0.008;
288:         ctx.fillStyle = '#ffe9b8';
289:         ctx.beginPath();
290:         ctx.moveTo(x, sunY);
291:         ctx.lineTo(x + Math.cos(ang) * 900 - 120, h + 80);
292:         ctx.lineTo(x + Math.cos(ang) * 900 + 5, h + 80);
293:         ctx.closePath();
294:         ctx.fill();
295:       }
296:       ctx.restore();
297:     }
298: 
299:     const haze = ctx.createLinearGradient(0, HORIZON - 130, 0, h);
300:     haze.addColorStop(0, 'rgba(0,0,0,0)');
301:     haze.addColorStop(0.55, t.fog);
302:     haze.addColorStop(1, t.fog);
303:     ctx.fillStyle = haze;
304:     ctx.fillRect(0, HORIZON - 130, w, h - HORIZON + 130);
305:   }
306: 
307:   drawBackdrop() {
308:     const ctx = this.ctx;
309:     const g = this.game;
310:     const t = g.level.theme;
311:     const cam = g.camera.x;
312:     if (!this.backdrop) return;
313: 
314:     const drawLayer = (layer, factor, colorFar, colorNear, yOffset, alpha, windowed) => {
315:       const shift = cam * factor;
316:       const w = this.viewW;
317:       for (const b of layer) {
318:         const x = b.x - shift;
319:         if (x + b.w < -40 || x > w + 40) continue;
320:         const bottom = b.bottom + yOffset;
321:         const top = bottom - b.h;
322:         const grad = ctx.createLinearGradient(0, top, 0, bottom);
323:         grad.addColorStop(0, colorFar);
324:         grad.addColorStop(1, colorNear);
325:         ctx.globalAlpha = alpha;
326:         ctx.fillStyle = grad;
327:         ctx.fillRect(x, top, b.w, b.h);
328:         ctx.globalAlpha = 1;
329: 
330:         if (windowed) {
331:           for (const wnd of b.windows) {
332:             const flick = wnd.flick < 0.12 ? (Math.sin(g.animTime * 4 + wnd.flick * 40) > 0.2 ? 1 : 0.25) : 1;
333:             ctx.globalAlpha = alpha * (wnd.warm ? 0.6 : 0.35) * flick;
334:             ctx.fillStyle = wnd.warm ? t.window : '#7fa2ad';
335:             ctx.fillRect(x + wnd.x, top + wnd.y, wnd.w, wnd.h);
336:           }
337:           ctx.globalAlpha = 1;
338:         }
339: 
340:         if (b.damaged) {
341:           ctx.fillStyle = colorNear;
342:           ctx.globalAlpha = alpha;
343:           ctx.beginPath();
344:           const cut = b.w * (0.2 + b.tone * 0.35);
345:           ctx.moveTo(x + cut, top);
346:           ctx.lineTo(x + cut + 8, top + 10 + b.tone * 20);
347:           ctx.lineTo(x + cut + 2, top + 18 + b.tone * 16);
348:           ctx.lineTo(x + cut + 12, top + 28 + b.tone * 30);
349:           ctx.lineTo(x + b.w, top + 18);
350:           ctx.lineTo(x + b.w, top);
351:           ctx.closePath();
352:           ctx.fill();
353:           ctx.globalAlpha = 1;
354:         }
355:         if (b.antenna) {
356:           ctx.strokeStyle = colorNear;
357:           ctx.globalAlpha = alpha * 0.9;
358:           ctx.lineWidth = 1;
359:           ctx.beginPath();
360:           ctx.moveTo(x + b.w * 0.65, top);
361:           ctx.lineTo(x + b.w * 0.65, top - 16 - b.tone * 30);
362:           ctx.stroke();
363:           ctx.globalAlpha = 1;
364:         }
365:       }
366:     };
367: 
368:     drawLayer(this.backdrop.far, 0.045, t.far, t.far, 6, 0.66, false);
369:     drawLayer(this.backdrop.mid, 0.145, t.mid, t.near, 4, 0.9, true);
370: 
371:     // smoke columns
372:     for (const s of this.backdrop.smoke) {
373:       const x = s.x - cam * 0.11;
374:       if (x < -180 || x > this.viewW + 180) continue;
375:       for (let i = 0; i < 8; i++) {
376:         const prog = ((g.animTime * s.speed + i * 0.18 + s.phase) % 1.4);
377:         const sx = x + Math.sin(prog * 5 + s.phase) * 14 + prog * s.drift;
378:         const sy = s.y - prog * 155;
379:         const r = s.s * (0.55 + prog * 2.2);
380:         const alpha = (1 - prog / 1.4) * 0.09;
381:         const sg = ctx.createRadialGradient(sx, sy, 0, sx, sy, r);
382:         sg.addColorStop(0, `rgba(54,56,54,${alpha})`);
383:         sg.addColorStop(0.6, `rgba(58,58,53,${alpha * 0.6})`);
384:         sg.addColorStop(1, 'rgba(30,30,28,0)');
385:         ctx.fillStyle = sg;
386:         ctx.fillRect(sx - r, sy - r, r * 2, r * 2);
387:       }
388:     }
389: 
390:     // cables and wires
391:     ctx.save();
392:     ctx.strokeStyle = '#060a0b';
393:     for (const wire of this.backdrop.wires) {
394:       const x1 = wire.x1 - cam * 0.19;
395:       const x2 = wire.x2 - cam * 0.19;
396:       if ((x1 < -200 && x2 < -200) || (x1 > this.viewW + 200 && x2 > this.viewW + 200)) continue;
397:       ctx.globalAlpha = wire.alpha;
398:       ctx.lineWidth = 1.2;
399:       ctx.beginPath();
400:       ctx.moveTo(x1, wire.y1);
401:       ctx.quadraticCurveTo((x1 + x2) / 2, (wire.y1 + wire.y2) / 2 + wire.sag, x2, wire.y2);
402:       ctx.stroke();
403:     }
404:     ctx.restore();
405: 
406:     drawLayer(this.backdrop.near, 0.31, '#070b0c', '#0a0f10', 20, 0.82, false);
407: 
408:     // distant ground haze
409:     const fog = ctx.createLinearGradient(0, HORIZON - 18, 0, HORIZON + 70);
410:     fog.addColorStop(0, 'rgba(0,0,0,0)');
411:     fog.addColorStop(1, t.fog);
412:     ctx.fillStyle = fog;
413:     ctx.fillRect(0, HORIZON - 18, this.viewW, 90);
414:   }
