419:   drawDecorations() {
420:     const g = this.game;
421:     const theme = g.level.theme;
422:     const cam = g.camera.x;
423:     for (const d of g.level.decorations || []) {
424:       if (d.x < cam - 260 || d.x > cam + this.viewW + 260) continue;
425:       this.drawDecoration(d, theme, g.animTime);
426:     }
