429:   drawDecoration(d, theme, time) {
430:     const ctx = this.ctx;
431:     const x = d.x;
432:     const y = d.y;
433:     ctx.save();
434:     ctx.translate(x, y);
435:     switch (d.type) {
436:       case 'wreck':
437:       case 'car': {
438:         const wreck = d.type === 'wreck';
439:         ctx.globalAlpha = 0.72;
440:         ctx.fillStyle = '#101617';
441:         ctx.beginPath();
442:         ctx.ellipse(0, 3, wreck ? 58 : 54, 8, 0, 0, TAU);
443:         ctx.fill();
444:         ctx.globalAlpha = 1;
445:         const body = wreck ? '#2b2521' : '#28383a';
446:         const body2 = wreck ? '#45352b' : '#3c5254';
447:         ctx.fillStyle = body;
448:         ctx.beginPath();
449:         ctx.moveTo(-52, -6);
450:         ctx.lineTo(-44, -28);
451:         ctx.lineTo(-12, -39);
452:         ctx.lineTo(12, -40);
453:         ctx.lineTo(39, -30);
454:         ctx.lineTo(49, -12);
455:         ctx.lineTo(52, -4);
456:         ctx.lineTo(48, 0);
457:         ctx.lineTo(-49, 0);
458:         ctx.closePath();
459:         ctx.fill();
460:         ctx.fillStyle = body2;
461:         ctx.beginPath();
462:         ctx.moveTo(-34, -25);
463:         ctx.lineTo(-16, -34);
464:         ctx.lineTo(2, -35);
465:         ctx.lineTo(4, -23);
466:         ctx.lineTo(-30, -22);
467:         ctx.closePath();
468:         ctx.fill();
469:         ctx.fillStyle = wreck ? '#171b1b' : '#152021';
470:         ctx.globalAlpha = 0.85;
471:         ctx.beginPath();
472:         ctx.moveTo(8, -35);
473:         ctx.lineTo(31, -27);
474:         ctx.lineTo(36, -14);
475:         ctx.lineTo(7, -16);
476:         ctx.closePath();
477:         ctx.fill();
478:         ctx.globalAlpha = 1;
479:         ctx.strokeStyle = wreck ? '#5b3b2a' : '#657774';
480:         ctx.globalAlpha = 0.4;
481:         ctx.lineWidth = 1.3;
482:         ctx.beginPath();
483:         ctx.moveTo(-20, -6);
484:         ctx.lineTo(18, -10);
485:         ctx.moveTo(-33, -8);
486:         ctx.lineTo(-45, -16);
487:         ctx.stroke();
488:         ctx.globalAlpha = 1;
489:         for (const wx of [-33, 32]) {
490:           ctx.fillStyle = '#0b0e0e';
491:           ellipse(ctx, wx, -2, 10, 10);
492:           ctx.fill();
493:           ctx.fillStyle = '#2e3534';
494:           ellipse(ctx, wx, -2, 4.5, 4.5);
495:           ctx.fill();
496:         }
497:         if (wreck) {
498:           ctx.fillStyle = '#c76b37';
499:           ctx.globalAlpha = 0.22;
500:           ctx.fillRect(-48, -18, 16, 8);
501:           ctx.fillRect(20, -11, 19, 5);
502:           ctx.globalAlpha = 1;
503:         }
504:         break;
505:       }
506:       case 'sandbags': {
507:         const bag = '#67593f';
508:         const bagLight = '#7e6b4b';
509:         for (let row = 0; row < 3; row++) {
510:           const count = 4 - row;
511:           for (let i = 0; i < count; i++) {
512:             const bx = (i - count / 2) * 21 + row * 6;
513:             const by = -7 - row * 10;
514:             ctx.fillStyle = bag;
515:             ellipse(ctx, bx, by, 12, 7.3, (i % 2 ? -0.08 : 0.06));
516:             ctx.fill();
517:             ctx.strokeStyle = bagLight;
518:             ctx.globalAlpha = 0.22;
519:             ctx.lineWidth = 0.8;
520:             ctx.stroke();
521:             ctx.globalAlpha = 1;
522:           }
523:         }
524:         break;
525:       }
526:       case 'barrier': {
527:         const gr = ctx.createLinearGradient(0, -46, 0, 0);
528:         gr.addColorStop(0, '#7e7768');
529:         gr.addColorStop(1, '#3c3d37');
530:         ctx.fillStyle = gr;
531:         ctx.beginPath();
532:         ctx.moveTo(-32, 0);
533:         ctx.lineTo(-28, -38);
534:         ctx.lineTo(28, -38);
535:         ctx.lineTo(32, 0);
536:         ctx.closePath();
537:         ctx.fill();
538:         ctx.fillStyle = '#d0a959';
539:         ctx.globalAlpha = 0.55;
540:         for (let i = -2; i <= 2; i++) {
541:           ctx.beginPath();
542:           ctx.moveTo(i * 13 - 4, -34);
543:           ctx.lineTo(i * 13 + 2, -34);
544:           ctx.lineTo(i * 13 + 9, -4);
545:           ctx.lineTo(i * 13 + 3, -4);
546:           ctx.closePath();
547:           ctx.fill();
