820:   /* Platforms                                                  */
821:   /* ---------------------------------------------------------- */
822:   drawPlatforms() {
823:     const ctx = this.ctx;
824:     const g = this.game;
825:     const cam = g.camera.x;
826:     const theme = g.level.theme;
827:     for (const p of g.runtime.platforms) {
828:       if (p.x + p.w < cam - 60 || p.x > cam + this.viewW + 60) continue;
829:       this.drawPlatform(p, theme);
830:     }
831:   }
