833:   drawPlatform(p, theme) {
834:     const ctx = this.ctx;
835:     const d = p.detail;
836:     if (p.kind === 'metal') {
837:       const gr = ctx.createLinearGradient(0, p.y, 0, p.y + Math.max(p.h, 34));
838:       gr.addColorStop(0, '#555a55');
839:       gr.addColorStop(0.18, '#343b39');
840:       gr.addColorStop(1, '#171c1c');
841:       ctx.fillStyle = gr;
842:       ctx.fillRect(p.x, p.y, p.w, p.h);
843:       ctx.fillStyle = '#767d73';
844:       ctx.fillRect(p.x, p.y, p.w, 3);
845:       ctx.fillStyle = 'rgba(219,177,99,.38)';
846:       ctx.fillRect(p.x, p.y + 3, p.w, 1);
847:       ctx.fillStyle = 'rgba(11,14,14,.7)';
848:       for (let i = 14; i < p.w - 10; i += 28) ctx.fillRect(p.x + i, p.y + 7, 2, p.h - 7);
849:       // hazard plates
850:       for (let i = 10; i < p.w - 24; i += 72) {
851:         ctx.fillStyle = 'rgba(205,158,77,.22)';
852:         ctx.save();
853:         ctx.beginPath();
854:         ctx.rect(p.x + i, p.y + p.h - 9, 34, 4);
855:         ctx.clip();
856:         ctx.fillRect(p.x + i, p.y + p.h - 9, 34, 4);
857:         ctx.fillStyle = 'rgba(12,14,12,.5)';
858:         for (let k = -2; k < 6; k++) {
859:           ctx.save();
860:           ctx.translate(p.x + i + k * 10, p.y + p.h - 9);
861:           ctx.rotate(-0.5);
862:           ctx.fillRect(0, 0, 4, 12);
863:           ctx.restore();
864:         }
865:         ctx.restore();
866:       }
867:       if (d) {
868:         ctx.strokeStyle = 'rgba(230,236,226,.16)';
869:         ctx.lineWidth = 1;
870:         for (const bolt of d.bolts) {
871:           ctx.beginPath();
872:           ctx.arc(bolt.x, bolt.y, 1.1, 0, TAU);
873:           ctx.stroke();
874:         }
875:       }
876:     } else if (p.kind === 'ground') {
877:       const gr = ctx.createLinearGradient(0, p.y, 0, p.y + 110);
878:       gr.addColorStop(0, theme.groundTop);
879:       gr.addColorStop(0.08, '#565046');
880:       gr.addColorStop(0.32, theme.groundBase);
881:       gr.addColorStop(1, theme.groundDeep);
882:       ctx.fillStyle = gr;
883:       ctx.fillRect(p.x, p.y, p.w, p.h);
884:       ctx.fillStyle = 'rgba(234,217,178,.3)';
885:       ctx.fillRect(p.x, p.y, p.w, 2);
886:       ctx.fillStyle = 'rgba(28,31,29,.38)';
887:       for (let i = 8; i < p.w; i += 78) ctx.fillRect(p.x + i, p.y + 8, 1, 30);
888:       // pavement seams
889:       ctx.strokeStyle = 'rgba(24,27,25,.3)';
890:       ctx.lineWidth = 1;
891:       for (let i = 70; i < p.w; i += 110) {
892:         ctx.beginPath();
893:         ctx.moveTo(p.x + i, p.y + 4);
894:         ctx.lineTo(p.x + i + 3, p.y + 18);
895:         ctx.stroke();
896:       }
897:       if (d) {
898:         ctx.strokeStyle = 'rgba(15,18,17,.38)';
899:         for (const crack of d.cracks) {
900:           ctx.beginPath();
901:           ctx.moveTo(p.x + crack.x, p.y + crack.y);
902:           ctx.lineTo(p.x + crack.x + crack.dx, p.y + crack.y + crack.dy);
903:           ctx.lineTo(p.x + crack.x + crack.dx * 1.5, p.y + crack.y + crack.dy * 1.8);
904:           ctx.stroke();
905:         }
906:         for (const stain of d.stains) {
907:           ctx.fillStyle = `rgba(18,17,15,${stain.a})`;
908:           ellipse(ctx, p.x + stain.x, p.y + stain.y, stain.w, stain.h);
909:           ctx.fill();
910:         }
911:       }
912:       // rebar sticking out at exposed ends
913:       if (d && d.rebar) {
914:         ctx.strokeStyle = '#8a5e35';
915:         ctx.lineWidth = 1.2;
916:         for (let i = 0; i < 4; i++) {
917:           ctx.beginPath();
918:           ctx.moveTo(p.x + p.w - 2, p.y + 16 + i * 10);
919:           ctx.lineTo(p.x + p.w + 8 + i * 2, p.y + 11 + i * 10);
920:           ctx.stroke();
921:         }
922:       }
923:     } else {
924:       const gr = ctx.createLinearGradient(0, p.y, 0, p.y + p.h);
925:       gr.addColorStop(0, '#6b6659');
926:       gr.addColorStop(0.2, '#4a4740');
927:       gr.addColorStop(1, '#202421');
928:       ctx.fillStyle = gr;
929:       ctx.fillRect(p.x, p.y, p.w, p.h);
930:       ctx.fillStyle = '#938977';
931:       ctx.fillRect(p.x, p.y, p.w, 3);
932:       ctx.strokeStyle = 'rgba(28,30,27,.35)';
933:       for (let i = 60; i < p.w; i += 60) {
934:         ctx.beginPath();
935:         ctx.moveTo(p.x + i, p.y + 4);
936:         ctx.lineTo(p.x + i, p.y + p.h);
937:         ctx.stroke();
938:       }
939:     }
940: 
941:     // top edge glint
942:     ctx.fillStyle = `rgba(${theme.accentRGB},.18)`;
943:     ctx.fillRect(p.x + 2, p.y - 1, p.w - 4, 1);
944:     ctx.fillStyle = 'rgba(0,0,0,.25)';
945:     ctx.fillRect(p.x, p.y + Math.min(6, p.h), p.w, 2);
946:   }
