948:   /* ---------------------------------------------------------- */
949:   /* Decals, hazards, extraction                                */
950:   /* ---------------------------------------------------------- */
951:   drawDecals() {
952:     const ctx = this.ctx;
953:     for (const d of this.game.runtime.decals) {
954:       const alpha = clamp(d.life / d.maxLife, 0, 1);
955:       if (d.type === 'blood') {
956:         ctx.globalAlpha = alpha * 0.38;
957:         ctx.fillStyle = '#5d1814';
958:         ellipse(ctx, d.x, d.y, d.size, d.size * 0.55, d.angle);
959:         ctx.fill();
960:         ctx.globalAlpha = alpha * 0.24;
961:         ellipse(ctx, d.x + d.size * 0.4, d.y + 2, d.size * 0.35, d.size * 0.2);
962:         ctx.fill();
963:       } else {
964:         ctx.globalAlpha = alpha * 0.62;
965:         ctx.fillStyle = '#0a0c0c';
966:         ellipse(ctx, d.x, d.y, d.size * 0.5, d.size * 0.36, d.angle);
967:         ctx.fill();
968:         ctx.strokeStyle = 'rgba(10,12,12,.36)';
969:         ctx.lineWidth = 0.8;
970:         ctx.beginPath();
971:         ctx.moveTo(d.x, d.y);
972:         ctx.lineTo(d.x + d.size * 0.8, d.y - d.size * 0.6);
973:         ctx.stroke();
974:       }
975:     }
976:     ctx.globalAlpha = 1;
977:   }
