979:   drawHazards() {
980:     const ctx = this.ctx;
981:     const g = this.game;
982:     for (const h of g.runtime.hazards) {
983:       if (h.x < g.camera.x - 120 || h.x > g.camera.x + this.viewW + 120) continue;
984:       if (h.type === 'fire') {
985:         const pulse = 0.8 + Math.sin(g.animTime * 9 + h.x) * 0.18;
986:         const baseY = h.y + h.h;
987:         ctx.fillStyle = '#30201a';
988:         ctx.fillRect(h.x - 5, baseY - 5, h.w + 10, 7);
989:         ctx.fillStyle = 'rgba(230,180,85,.22)';
990:         ctx.fillRect(h.x - 5, baseY - 5, h.w + 10, 1);
991:         const glow = ctx.createRadialGradient(h.x + h.w / 2, baseY - 25, 0, h.x + h.w / 2, baseY - 25, 85);
992:         glow.addColorStop(0, 'rgba(255,121,42,.18)');
993:         glow.addColorStop(1, 'rgba(255,121,42,0)');
994:         ctx.fillStyle = glow;
995:         ctx.fillRect(h.x - 60, baseY - 110, h.w + 120, 150);
996:         ctx.save();
997:         ctx.globalCompositeOperation = 'lighter';
998:         for (let i = 0; i < 5; i++) {
999:           const fx = h.x + h.w * (0.15 + i * 0.18) + Math.sin(g.animTime * 11 + i) * 4;
1000:           const fh = h.h * (0.48 + i * 0.1) * pulse;
1001:           const grad = ctx.createLinearGradient(fx, baseY, fx, baseY - fh);
1002:           grad.addColorStop(0, 'rgba(255,97,25,.62)');
1003:           grad.addColorStop(0.5, 'rgba(255,165,48,.48)');
1004:           grad.addColorStop(1, 'rgba(255,235,150,0)');
1005:           ctx.fillStyle = grad;
1006:           ctx.beginPath();
1007:           ctx.moveTo(fx - 8, baseY - 2);
1008:           ctx.quadraticCurveTo(fx - 16 + Math.sin(g.animTime * 6 + i) * 4, baseY - fh * 0.62, fx + Math.sin(g.animTime * 4 + i) * 3, baseY - fh);
1009:           ctx.quadraticCurveTo(fx + 13 + Math.sin(g.animTime * 5 + i) * 4, baseY - fh * 0.56, fx + 8, baseY - 2);
1010:           ctx.closePath();
1011:           ctx.fill();
1012:         }
1013:         ctx.restore();
1014:       } else if (h.type === 'electric') {
1015:         const pulse = 0.5 + Math.sin(g.animTime * 14 + h.x) * 0.5;
1016:         ctx.fillStyle = '#272d2a';
1017:         ctx.fillRect(h.x - 6, h.y + h.h - 5, h.w + 12, 5);
1018:         ctx.fillStyle = '#7e8b84';
1019:         ctx.fillRect(h.x, h.y + 8, h.w, 2);
1020:         ctx.fillStyle = 'rgba(139,215,232,.32)';
1021:         ctx.fillRect(h.x, h.y + 8, h.w, 1);
1022:         ctx.save();
1023:         ctx.globalCompositeOperation = 'lighter';
1024:         ctx.strokeStyle = `rgba(137,224,242,${0.35 + pulse * 0.5})`;
1025:         ctx.lineWidth = 1.2;
1026:         for (let i = 0; i < 3; i++) {
1027:           ctx.beginPath();
1028:           ctx.moveTo(h.x + 4, h.y + h.h - 6);
1029:           let xx = h.x + 4;
1030:           let yy = h.y + h.h - 6;
1031:           for (let k = 0; k < 4; k++) {
