1372:   updateGroundEnemy(e, cfg, dt, dx, dy, dist, px, py) {
1373:     e.vx = 0;
1374:     if (e.alert) {
1375:       e.facing = dx >= 0 ? 1 : -1;
1376:       if (dist > 250 && e.hasLOS) {
1377:         e.vx = e.facing * cfg.speed;
1378:       } else if (!e.hasLOS && dist > 300) {
1379:         e.vx = e.facing * cfg.speed * 0.45;
1380:       }
1381:     } else {
1382:       if (Math.abs(e.x - e.patrolOrigin) > e.patrolRange) {
1383:         e.patrolDir = e.x > e.patrolOrigin ? -1 : 1;
1384:       }
1385:       e.vx = e.patrolDir * cfg.speed * 0.48;
1386:       e.facing = e.patrolDir;
1387:       e.aimAngle = this.rotateTowards(e.aimAngle, e.patrolDir > 0 ? 0 : Math.PI, dt * 3);
1388:     }
1389:     e.vy = Math.min(e.vy + GRAVITY * dt, MAX_FALL);
1390:     const oldX = e.x;
1391:     this.moveActor(e, dt);
1392:     if (e.vx === 0 && e.grounded && e.alert && Math.abs(dx) > 250) {
1393:       // A wall or ledge stopped the advance; hold position.
1394:     }
1395:     if (e.grounded && Math.abs(e.vx) > 2) {
1396:       const frontX = e.vx > 0 ? e.x + e.w + 4 : e.x - 4;
1397:       if (!this.hasSupport(frontX, e.y + e.h + 5)) {
1398:         if (e.alert) e.vx = 0;
1399:         else {
1400:           e.patrolDir *= -1;
1401:           e.facing = e.patrolDir;
1402:           e.x = oldX;
1403:         }
1404:       }
1405:     }
1406:     e.x = clamp(e.x, 0, this.level.width - e.w);
