1409:   updateDrone(e, cfg, dt, dx, dy, dist, px, py) {
1410:     const t = this.animTime;
1411:     if (dist < cfg.aggro && (e.hasLOS || dist < 320)) e.alert = true;
1412:     e.phase += dt * 1.8;
1413:     let targetX;
1414:     let targetY;
1415:     if (e.alert) {
1416:       targetX = px - (e.startX % 2 === 0 ? 1 : -1) * 130;
1417:       targetY = py - 112 + Math.sin(e.phase) * 15;
1418:     } else {
1419:       targetX = e.startX + Math.sin(e.phase * 0.4) * 75;
1420:       targetY = e.startY + Math.sin(e.phase) * e.amp;
1421:     }
1422:     const dxT = targetX - (e.x + e.w / 2);
1423:     const dyT = targetY - (e.y + e.h / 2);
1424:     const dT = Math.hypot(dxT, dyT) || 1;
1425:     const sp = cfg.speed;
1426:     e.vx = (dxT / dT) * sp;
1427:     e.vy = (dyT / dT) * sp * 0.85;
1428:     e.x += e.vx * dt;
1429:     e.y += e.vy * dt;
1430:     e.x = clamp(e.x, 12, this.level.width - e.w - 12);
1431:     e.y = clamp(e.y, 90, 555);
1432:     e.facing = dx >= 0 ? 1 : -1;
1433:     e.aimAngle = this.rotateTowards(e.aimAngle, Math.atan2(dy, dx), dt * 7);
1434:     e.aimX = e.facing * 5;
1435:   }
