1437:   rotateTowards(current, target, maxStep) {
1438:     let delta = (target - current + Math.PI * 3) % TAU - Math.PI;
1439:     if (Math.abs(delta) <= maxStep) return target;
1440:     return current + Math.sign(delta) * maxStep;
1441:   }
