1201:               hit = true;
1202:               break;
1203:             }
1204:           }
1205:           if (hit) break;
1206:           if (this.boss && this.boss.active && !this.boss.dead) {
1207:             const boss = this.boss;
1208:             if (pointInRect(b.x, b.y, { x: boss.x - 8, y: boss.y - 6, w: boss.w + 16, h: boss.h + 12 })) {
1209:               if (b.rocket) {
1210:                 this.explode(b.x, b.y, b.explosive?.radius || 110, b.explosive?.damage || 100, 'player');
1211:                 this.damageBoss(b.damage);
